    H2 = '자료의 합 = 평균 × 자료의 수. 모르는 값 = 합 − 아는 값들의 합'
    H3 = '가능성의 크기: 불가능하다 < ~아닐 것 같다 < 반반이다 < ~일 것 같다 < 확실하다'
    H4 = '불가능하다 → 0, 반반이다 → 1/2, 확실하다 → 1'
    H5 = '원하는 것이 나머지보다 많으면 "~일 것 같다", 같으면 "반반이다", 적으면 "~아닐 것 같다"예요.'
    def q(qid, d, text, ans, wrongs, *hs):
        if len(hs) == 5: hs = hs[1:]
        return Q(b, qid, d, text, ans, wrongs, *hs)
    def t(tid, d, text, ans, h1, h2, h3): return T(b, tid, d, text, ans, h1, h2, h3)
    def wq(qid, d, text, ans, h1, h2, ex, step, tags=None):
        tags = tags or {}
        ws = [(w, tags.get(w, 'word')) for w in W if w != ans]
        # 보기 4개: 정답과 가장 가까운 셋
        i = W.index(ans)
        ws.sort(key=lambda x: abs(W.index(x[0]) - i))
        return q(qid, d, text + ' 가장 알맞은 말을 고르세요.', ans, ws[:3], H3, h1, h2, ex, step)

